Project automationToolSong(){auto p=emptyProject();p.title="Automation tools native verification";p.bpm=120;p.swing=0;p.songMode=true;p.loop=true;p.patterns[0].length=4;p.patterns[0].lanes[7]={{0,4,60,.8f}};p.tracks[7].send=0;p.clips.push_back({7,0,0,4});Clip c;c.track=7;c.automationTrack=7;c.automationTarget=0;c.length=4;c.points={{0,.15f,false},{2,.9f,false},{4,.3f,false}};p.clips.push_back(c);return p;}
Component* generatorPanel(AlertWindow* dialog){return dialog?dialog->findChildWithID("automation-generator-panel"):nullptr;}
void field(Component* panel,const char* name,const String& text){if(panel)if(auto* value=dynamic_cast<TextEditor*>(panel->findChildWithID("automation-"+String(name)))){value->setText(text);if(value->onTextChange)value->onTextChange();}}
bool dialogImage(AlertWindow* dialog,const File& file){PNGImageFormat format;FileOutputStream stream(file);return dialog&&stream.openedOk()&&format.writeImageToStream(dialog->createComponentSnapshot(dialog->getLocalBounds()),stream);}
