    reset();context=automationToolContext();auto before=JSON::toString(projectToJson(project));selectedClip=0;check(!applyAutomationPoints(*context,shaped,false)&&JSON::toString(projectToJson(project))==before,"changing the selected clip invalidates a captured curve editor");selectedClip=1;changed(false);check(!applyAutomationPoints(*context,shaped,false),"a newer revision blocks stale shape Apply");reset();context=automationToolContext();project.clips[1].points[0].value=.2f;check(!applyAutomationPoints(*context,shaped,false),"unpublished source-point changes also invalidate a captured tool");reset();context=automationToolContext();recording=true;check(!automationToolContext()&&!applyAutomationPoints(*context,shaped,false),"recording locks both shape capture and Apply");recording=false;selectedTrack=7;selectedNotes={0};selectedNote=0;perform(grooveOpen);auto gs=grooveSettings;gs.velocity=1;gs.pattern.steps[0].velocity=.25f;acceptGrooveSettings(gs,revision,grooveSerial);check(pendingNoteTool()&&!automationToolContext(),"pending note edits cannot be bypassed by automation tools");cancelNoteTool();reset();
