    context=automationToolContext();AutomationGenerator settings;settings.period=2;settings.low=.1;settings.high=.8;std::vector<AutomationPoint> generated;generateAutomation(4,settings,generated);check(applyAutomationPoints(*context,generated)&&project.clips[1].points.size()==33&&undoStack.size()==1&&project.clips[1].automationTrack==7&&project.clips[0].pattern==0,"generator Apply replaces only selected clip points as one Undo");prepareToPlay(1024,48000);activeOutputs.store(2);activeInputs.store(0);perform(play);AudioBuffer<float> block(2,4096);float peak=0;for(int i=0;i<16;++i){getNextAudioBlock(AudioSourceChannelInfo(&block,0,4096));peak=jmax(peak,block.getMagnitude(0,0,4096));}perform(stop);check(peak>.001f,"generated automation drives audible real callback output");
    auto file=folder.getChildFile("automation-tools.pulse");Project read;check(saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&read.clips[1].points==generated,"native project save and reload retain generated segment settings");perform(undoAction);check(project.clips[1].points==source,"Undo generation restores the previous editable phrase");perform(redoAction);check(project.clips[1].points==generated,"Redo generation restores every generated point");selectedClip=1;selectedPoint=0;showPane(automationPane);perform(copySelection);automationCursor=.0625;perform(pasteSelection);check(project.clips[1].points.size()==34&&project.clips[1].points[1].value==generated[0].value,"automation clipboard pastes generated point data at its own cursor");perform(undoAction);
    reset();context=automationToolContext();auto invalid=source;invalid[0].curve=(AutomationCurve)9;before=JSON::toString(projectToJson(project));check(!applyAutomationPoints(*context,invalid,false)&&JSON::toString(projectToJson(project))==before&&undoStack.empty(),"invalid segment metadata rejects before checkpointing or publication");selectedPoint=0;project.clips[1].points[0].curve=AutomationCurve::easeIn;project.clips[1].points[0].tension=.4f;publish();perform(copySelection);automationCursor=1;perform(pasteSelection);check(project.clips[1].points[1].curve==AutomationCurve::easeIn&&project.clips[1].points[1].tension==.4f,"copy/paste retains curve and tension for a manually shaped segment");perform(undoAction);selectedClip=1;showPane(automationPane);snapshot(folder.getChildFile("automation-shapes.png"));bool shape=false,generator=false;for(const auto& hit:hits)if(hit.pane==automationPane){shape|=hit.action==automationShapeOpen;generator|=hit.action==automationGenerateOpen;}check(shape&&generator,"automation editor exposes working Shape and Generate controls");auto entries=paletteEntries();bool searchedShape=false,searchedGenerator=false;for(const auto& entry:entries){searchedShape|=entry.action==automationShapeOpen&&entry.enabled;searchedGenerator|=entry.action==automationGenerateOpen&&entry.enabled;}check(searchedShape&&searchedGenerator,"command search discovers enabled curve and generator tools");
